// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Tunnel".

Just one of those tunnel things.

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Forward / Backward in time

*/

const scale = Math.max(1, devicePixelRatio)
let theShader, wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2986290/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, .05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define T (time+wheel.y/1e3)
#define S smoothstep
#define MN min(R.x,R.y)
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(1,2,3)))
float rect(vec2 p, vec2 s) {
	p=abs(p)-s;
	return max(p.x,p.y);
}
vec3 aces(vec3 v) {
	v=max(v*.6,.0);
  float
  a=2.51, b=.03,
  c=2.43, d=.59, e=.14;
  return clamp((v*(a*v+b))/(v*(c*v+d)+e),.0,1.);
}
void main() {
	vec2 uv=(FC-.5*R)/MN, p=uv;
	vec3 col=vec3(0);
	p+=sin(T-p*vec2(10,-3))*.02;
	float g=S(.0,.125,length(p));
	p=vec2(log(length(p))-T*.2,atan(p.x,p.y)*6./6.28318);
	for (float i=.0; i<3.; i++) {
		p=fract(p)-.5;
		float d=rect(p,p/p)/(.1+exp(-1.+dot(p,p)));
		d=sin(12.*d+T)/3.;
		d=max(d,sin(-d*.125))/3.;
		col+=.0125/pow(d,.8)*hue(length(p)+i+T*.2);
	}
	col=S(1.,-.2,col);
	col=mix(S(.2,2.,col*col),col,g);
	col=aces(col)*1.2;
	float scanline=sin(T-uv.y*800.)*.01;
	uv=FC/R*2.-1.;
	uv*=.95;
	uv*=uv*uv*uv*uv;
	float v=pow(dot(uv,uv),.8);
	col=mix(col,vec3(0),v);
	col+=scanline;
	O=vec4(col,1);
}

